{
  "ingredients": [
    {
      "name": "土豆",
      "quantity": "4个中等大小"
    },
    {
      "name": "洋葱",
      "quantity": "1个"
    },
    {
      "name": "鸡蛋",
      "quantity": "6个"
    },
    {
      "name": "橄榄油",
      "quantity": "大量"
    },
    {
      "name": "盐",
      "quantity": "适量"
    }
  ],
  "steps": [
    "将土豆去皮切薄片,洋葱切碎。",
    "在大量橄榄油中以中火煎土豆和洋葱15分钟。",
    "在大碗中加盐打入鸡蛋,搅拌均匀。",
    "将土豆和洋葱与鸡蛋混合,静置5分钟。",
    "倒入加少许油的热锅中。",
    "每面煎4分钟,至金黄熟透。"
  ]
}
